const SEED=7;
function prng(s){return function(){s=(s*1664525+1013904223)>>>0;return s/4294967296;};}
const r=prng(SEED);
const bank=["Tell Me About Yourself", "What Is Your Greatest Weakness", "Tell Me About a Time You Failed", "Describe a Conflict With a Coworker", "Why Do You Want This Job", "Where Do You See Yourself in Five Years"];
const picks=[];const pool=bank.slice();
for(let i=0;i<3&&pool.length;i++){picks.push(pool.splice((r()*pool.length)|0,1)[0]);}
console.log(JSON.stringify({feature:'Mock interview round',seed:SEED,questions:picks,format:'2 minutes per answer, STAR structure'}));

